private fun icon(pathData: String) = lazy { vector(pathData, autoMirror = false) }

private fun mirrored(pathData: String) = lazy { vector(pathData, autoMirror = true) }

// Symbols use the viewBox "0 -960 960 960": move the path down by one viewport height.
private fun vector(pathData: String, autoMirror: Boolean) = ImageVector.Builder(
    defaultWidth = 24.dp,
    defaultHeight = 24.dp,
    viewportWidth = 960f,
    viewportHeight = 960f,
    autoMirror = autoMirror,
).addGroup(translationY = 960f)
    .addPath(addPathNodes(pathData), fill = SolidColor(Color.Black))
    .clearGroup()
    .build()
